package in.kabadiwala.connect.security; import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.Date; @Service public class JwtService {private final SecretKey key;private final long mins;public JwtService(@Value("${app.jwt-secret}")String s,@Value("${app.jwt-expiry-minutes:15}")long m){if(s.length()<32)throw new IllegalStateException("JWT secret must be at least 32 characters");key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));mins=m;}public String issue(String id,String role){return Jwts.builder().subject(id).claim("role",role).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofMinutes(mins)))).signWith(key).compact();}public Claims parse(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();}public long expirySeconds(){return mins*60;}}
